/** Builds a `srcSet` string from a photo's derivative list. */
export const buildSrcSet = (webp) =>
  webp.map(({ src, w }) => `${src} ${w}w`).join(", ");

/** The widest derivative's URL — for CSS backgrounds, which can't use srcSet. */
export const largestWebp = (photo) => photo.webp[photo.webp.length - 1].src;

